import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../../models/vehicle.dart';
import '../../services/app_state.dart';
import '../host/host_screen.dart';
class ProfileScreen extends StatelessWidget { const ProfileScreen({super.key}); @override Widget build(BuildContext context){final s=context.watch<AppState>();return Scaffold(appBar:AppBar(title:const Text('Meu perfil')),body:ListView(padding:const EdgeInsets.all(20),children:[CircleAvatar(radius:38,child:Text(s.userName.isEmpty?'U':s.userName[0].toUpperCase(),style:const TextStyle(fontSize:28))),const SizedBox(height:12),Center(child:Text(s.userName,style:const TextStyle(fontSize:20,fontWeight:FontWeight.bold))),const SizedBox(height:24),Card(child:ListTile(leading:const Icon(Icons.directions_car_outlined),title:Text(s.vehicle==null?'Cadastrar veículo':'${s.vehicle!.brand} ${s.vehicle!.model}'),subtitle:Text(s.vehicle==null?'Informe o veículo para realizar reservas':'${s.vehicle!.connector} • ${s.vehicle!.batteryKwh} kWh'),onTap:()=>_vehicle(context))),Card(child:ListTile(leading:const Icon(Icons.home_work_outlined),title:const Text('Quero ser anfitrião'),subtitle:const Text('Cadastre seu carregador e monetize a infraestrutura'),onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const HostScreen())))),Card(child:ListTile(leading:const Icon(Icons.settings_outlined),title:const Text('Configurações'),onTap:()=>showAboutDialog(context:context,applicationName:'EV Marketplace',applicationVersion:'0.1.0'))),const SizedBox(height:12),OutlinedButton(onPressed:()=>s.logout(),child:const Text('Sair'))]));}
 void _vehicle(BuildContext context){final b=TextEditingController();final m=TextEditingController();showDialog(context:context,builder:(_)=>AlertDialog(title:const Text('Meu veículo'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:b,decoration:const InputDecoration(labelText:'Marca')),TextField(controller:m,decoration:const InputDecoration(labelText:'Modelo'))]),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Cancelar')),FilledButton(onPressed:(){context.read<AppState>().saveVehicle(Vehicle(brand:b.text.isEmpty?'Veículo':b.text,model:m.text.isEmpty?'Elétrico':m.text,connector:'Tipo 2',batteryKwh:50));Navigator.pop(context);},child:const Text('Salvar'))]));}
}
